import { defineStore } from "pinia";
import { ref } from "vue";

export const contactUiStore = defineStore("contact", () => {
  const showElePage = ref(false);
  const showCheck = ref(false);
  const deleteData = ref("");

  const SendContact = async (inputData) => {
    const responsePost = await fetch("/api/send-contact", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(inputData),
    });

    if (!responsePost.ok) {
      throw new Error("Network response was not ok");
    }
  };

  const GetContactData = async () => {
    const response = await fetch("/api/get-contact");
    const data = await response.json();

    return data.data;
  };

  const DeleteContact = async (inputData) => {
    const responsePost = await fetch("/api/delete-contact", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ id: inputData }),
    });

    if (!responsePost.ok) {
      throw new Error("Network response was not ok");
    }
  };

  return {
    showElePage,
    showCheck,
    deleteData,
    SendContact,
    GetContactData,
    DeleteContact,
  };
});
